contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testRegression_property() public {
        address ownerBefore = c.owner();
        vm.prank(ownerBefore);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
